class LibraryMember{protected String memberId;protected int borrowLimit;private int borrowed;LibraryMember(String i,int l){if(i==null||i.trim().length()<4||l<=0)throw new IllegalArgumentException();memberId=i;borrowLimit=l;}void borrowBook(){if(borrowed<borrowLimit)borrowed++;}int getBooksBorrowed(){return borrowed;}String displayInfo(){return "General Member | Books Borrowed: "+borrowed;}static String enrollBatch(String[] ids,int limit){int e=0,r=0;for(String id:ids)try{new LibraryMember(id,limit);e++;}catch(IllegalArgumentException x){r++;}return "Enrolled: "+e+" | Rejected: "+r;}protected void chargeFine(int amount){fineHistory[fineCount++]=amount;}private int[] fineHistory=new int[10];private int fineCount;int[] getFineHistory(){return java.util.Arrays.copyOf(fineHistory,fineCount);}int getTotalFine(){int s=0;for(int x:getFineHistory())s+=x;return s;}}
class StudentMember extends LibraryMember{String course;StudentMember(String i,int l,String c){super(i,l);course=c;}String displayInfo(){return "Student Member | Course: "+course+" | Books Borrowed: "+getBooksBorrowed();}@Override protected void chargeFine(int amount){super.chargeFine(amount/2);}}
